-- IF JOIN CALL PREPARE inside a comment must not count.
CREATE PROCEDURE TEST.DYNAMIC_PROC
(
  IN P_SCHEMA VARCHAR(128),
  OUT P_COUNT INTEGER
)
LANGUAGE SQL
BEGIN
  DECLARE V_SQL VARCHAR(1000);
  SET V_SQL = 'SELECT COUNT(*) FROM X WHERE NOTE = ''IF JOIN''';
  PREPARE S1 FROM V_SQL;
  EXECUTE S1 INTO P_COUNT;
END;
